/**
 * IndexedDB 产品存储层
 * 产品数据（含 Base64 图片）存储在 IndexedDB 中，避免 localStorage 5MB 配额限制
 * 数据库名：app_ledlight_products_db
 * 对象仓库：products（主键 id）
 */

import type { IProduct } from '@/hooks/useProducts';

const DB_NAME = 'app_ledlight_products_db';
const DB_VERSION = 1;
const STORE_NAME = 'products';

let dbPromise: Promise<IDBDatabase> | null = null;

/**
 * 打开数据库（单例）
 */
function openDB(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;

  dbPromise = new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB not supported'));
      return;
    }

    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => {
      reject(request.error ?? new Error('Failed to open IndexedDB'));
    };

    request.onsuccess = () => {
      resolve(request.result);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        store.createIndex('createdAt', 'createdAt', { unique: false });
        store.createIndex('category', 'category', { unique: false });
      }
    };
  });

  return dbPromise;
}

/**
 * 获取所有产品（按 createdAt 倒序）
 */
export async function getAllProducts(): Promise<IProduct[]> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => {
      const products = (request.result ?? []) as IProduct[];
      // 按创建时间倒序
      products.sort((a, b) => b.createdAt - a.createdAt);
      resolve(products);
    };

    request.onerror = () => {
      reject(request.error ?? new Error('Failed to get products'));
    };
  });
}

/**
 * 根据 ID 获取产品
 */
export async function getProductById(id: string): Promise<IProduct | undefined> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(id);

    request.onsuccess = () => {
      resolve(request.result as IProduct | undefined);
    };

    request.onerror = () => {
      reject(request.error ?? new Error('Failed to get product'));
    };
  });
}

/**
 * 添加产品
 */
export async function addProduct(product: IProduct): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.add(product);

    request.onsuccess = () => resolve();
    request.onerror = () => {
      reject(request.error ?? new Error('Failed to add product'));
    };
  });
}

/**
 * 批量添加产品（用于迁移）
 */
export async function addProductsBatch(products: IProduct[]): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);

    products.forEach((p) => {
      store.put(p);
    });

    tx.oncomplete = () => resolve();
    tx.onerror = () => {
      reject(tx.error ?? new Error('Failed to batch add products'));
    };
    tx.onabort = () => {
      reject(tx.error ?? new Error('Batch add aborted'));
    };
  });
}

/**
 * 更新产品
 */
export async function updateProduct(product: IProduct): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.put(product);

    request.onsuccess = () => resolve();
    request.onerror = () => {
      reject(request.error ?? new Error('Failed to update product'));
    };
  });
}

/**
 * 删除产品
 */
export async function deleteProduct(id: string): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.delete(id);

    request.onsuccess = () => resolve();
    request.onerror = () => {
      reject(request.error ?? new Error('Failed to delete product'));
    };
  });
}

/**
 * 清空所有产品
 */
export async function clearAllProducts(): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const request = store.clear();

    request.onsuccess = () => resolve();
    request.onerror = () => {
      reject(request.error ?? new Error('Failed to clear products'));
    };
  });
}

/**
 * 检查 IndexedDB 中是否有数据
 */
export async function hasProducts(): Promise<boolean> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.count();

    request.onsuccess = () => resolve((request.result ?? 0) > 0);
    request.onerror = () => reject(request.error ?? new Error('Failed to count products'));
  });
}

/**
 * 批量更新多个产品（用于 Storage 优化：同步成功后替换 base64 为 GitHub 路径）
 */
export async function updateProductsBatch(products: IProduct[]): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);

    let completed = 0;
    const total = products.length;
    if (total === 0) {
      resolve();
      return;
    }

    const checkDone = () => {
      completed += 1;
      if (completed >= total) resolve();
    };

    for (const product of products) {
      const req = store.put(product);
      req.onsuccess = checkDone;
      req.onerror = () => {
        reject(req.error ?? new Error('Failed to batch update products'));
      };
    }

    tx.onerror = () => {
      reject(tx.error ?? new Error('Batch update transaction failed'));
    };
  });
}
